// C documentation
//
//	// Wide vec2
type b2Vec2W4 struct {
	X b2FloatW4
	Y b2FloatW4
}

// C documentation
//
//	// Wide rotation
type b2RotW4 struct {
	C b2FloatW4
	S b2FloatW4
}

// C documentation
//
//	// a - b
func b2SubVW(tls *_Stack, a b2Vec2W4, b b2Vec2W4) (r b2Vec2W4) {
	return b2Vec2W4{
		X: b2SubW(tls, a.X, b.X),
		Y: b2SubW(tls, a.Y, b.Y),
	}
}

func b2RightPerpW(tls *_Stack, a b2Vec2W4) (r b2Vec2W4) {
	return b2Vec2W4{
		X: a.Y,
		Y: b2NegW(tls, a.X),
	}
}

func b2DotW(tls *_Stack, a b2Vec2W4, b b2Vec2W4) (r b2FloatW4) {
	return b2AddW(tls, b2MulW(tls, a.X, b.X), b2MulW(tls, a.Y, b.Y))
}

func b2CrossW(tls *_Stack, a b2Vec2W4, b b2Vec2W4) (r b2FloatW4) {
	return b2SubW(tls, b2MulW(tls, a.X, b.Y), b2MulW(tls, a.Y, b.X))
}

func b2RotateVectorW(tls *_Stack, q b2RotW4, v b2Vec2W4) (r b2Vec2W4) {
	return b2Vec2W4{
		X: b2SubW(tls, b2MulW(tls, q.C, v.X), b2MulW(tls, q.S, v.Y)),
		Y: b2AddW(tls, b2MulW(tls, q.S, v.X), b2MulW(tls, q.C, v.Y)),
	}
}

