// Record framing

func b2RecBeginRecord(tls *_Stack, rec uintptr, opcode uint8) {
	bp := tls.Alloc(16)
	defer tls.Free(16)
	var _ /* zero at bp+0 */ [3]uint8_t
	b2RecW_U8(tls, rec, opcode)
	(*b2Recording)(unsafe.Pointer(rec)).RecordStart = (*b2Recording)(unsafe.Pointer(rec)).Buffer.Size
	// Make space to hold a 24-bit payload size, which isn't known until b2RecEndRecord is called.
	*(*[3]uint8_t)(unsafe.Add(nil, bp)) = [3]uint8_t{}
	b2RecBufAppend(tls, rec, bp, int32(3))
}

func b2RecEndRecord(tls *_Stack, rec uintptr) {
	var p uintptr
	var payloadSize int32
	var v1 bool
	_, _, _ = p, payloadSize, v1
	// Compute the final payload size and record it in the 24-bit space reserved right after the opcode.
	payloadSize = (*b2Recording)(unsafe.Pointer(rec)).Buffer.Size - (*b2Recording)(unsafe.Pointer(rec)).RecordStart - int32(3)
	if v1 = !!(payloadSize >= 0 && payloadSize < int32FromInt32(1)<<int32FromInt32(24)); !v1 {
		b2InternalAssert(tls, __ccgo_ts+20701, __ccgo_ts+20674, int32FromInt32(612))
	}
	_ = v1 || bool(int32FromInt32(0) != 0)
	p = (*b2Recording)(unsafe.Pointer(rec)).Buffer.Data + uintptr((*b2Recording)(unsafe.Pointer(rec)).RecordStart)
	*(*uint8_t)(unsafe.Add(nil, p)) = uint8FromInt32(payloadSize)
	*(*uint8_t)(unsafe.Add(nil, p+1)) = uint8FromInt32(payloadSize >> int32FromInt32(8))
	*(*uint8_t)(unsafe.Add(nil, p+2)) = uint8FromInt32(payloadSize >> int32FromInt32(16))
}

// Codegen pass 1b: arg writers. Each generated function writes its struct fields to the buffer
// Example:
// B2_REC_OP( 0x80, Step, RET_NONE, ARG( WORLDID, world ) ARG( F32, dt ) ARG( I32, subStepCount ) )
// Becomes:
// void b2RecWriteArgs_Step( b2Recording* rec, const b2RecArgs_Step* a)
// {
//   b2RecW_WORLDID( &rec->buffer, a->world );
//   b2RecW_F32( &rec->buffer, a->dt );
//   b2RecW_I32( &rec->buffer, a->subStepCount );
// }
// SPDX-FileCopyrightText: 2026 Erin Catto
// SPDX-License-Identifier: MIT

// X-macro manifest for the recording system.
// Include with B2_REC_OP and ARG defined. No commas between ARG tokens.
//
// B2_REC_OP( opcode, Name, RET, ARGS )
//   RET in { RET_NONE, RET_BODYID, RET_SHAPEID }
//   ARGS = zero or more ARG( TAG, fieldName ) tokens, NO commas between them
//
// Opcode ranges:
//   0x00-0x0F  world lifecycle and config
//   0x10-0x1F  body create/destroy
//   0x20-0x3F  body mutators
//   0x40-0x4F  shape create/destroy
//   0x50-0x6F  shape mutators
//   0x70-0x7F  chain
//   0x80       step
//   0x90-0xDF  joints (create, generic, per-type)
//   0xE0-0xEF  spatial queries
//   0xF0-0xFF  markers

// C documentation
