	b2RecBufAppend(tls, recording, (*(*b2RecBuffer)(unsafe.Add(nil, bp))).Data, (*(*b2RecBuffer)(unsafe.Add(nil, bp))).Size)
	b2RecBufFree(tls, bp)
	(*b2World)(unsafe.Pointer(world)).Recording = recording
	if b2ComputeWorldBounds(tls, world, bp+56) != 0 {
		b2RecAccumulateBounds(tls, recording, *(*AABB)(unsafe.Add(nil, bp+56)))
	}
	// Anchor the recorded state hash so replay verifies the blob deserialized to the same world.
